const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='python-garden-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{}state=Object.assign({version:1,profile:{daily:30,goal:'日常自动化',level:'完全零基础',style:'边做边学',os:'macOS'},done:[],notes:{},codes:{},attempts:{},favorites:[],mastery:{},project:{steps:[],code:''},seconds:0,last:0,theme:'light'},state||{});let saving=true;if(!state.tutorialRevision){state.font=16;state.outlineMode=false;state.tutorialRevision=1;save()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saving=true}catch(e){saving=false;toast('保存失败：浏览器存储空间不足，请导出备份。')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
const NAV_ICONS=['M4 4h6v16H4z M14 4h6v16h-6z', 'M5 5h5v5H5z M14 14h5v5h-5z M10 7h7v7', 'm8 6-6 6 6 6 M16 6l6 6-6 6 M14 4l-4 16', 'M3 7h7l2 3h9v10H3z M3 7V4h7l2 3', 'M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h5', 'M3 10a9 9 0 1 1 1 8 M3 4v6h6 M12 7v5l3 2', 'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2', 'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16'];
function navIcon(index){return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${NAV_ICONS[index]}"/></svg>`}
const NAV=[['route','','课程'],['paths','','路线'],['exercises','','练习'],['projects','','项目'],['notes','','笔记'],['review','','复习'],['settings','','设置'],['resources','','资料']];let worker=null,timer=null,running=false,route='',runToken=0;
function go(s){if(location.hash==='#'+s)render();else location.hash=s}window.go=go;function progress(){return Math.round(state.done.length/LESSONS.length*100)}function passed(){return Object.values(state.attempts).filter(x=>x.passed).length}function nextLesson(){return LESSONS.find(l=>!state.done.includes(l.id))||LESSONS[0]}function relatedExercise(id){return EXERCISES.find(x=>x.lesson===id)?.id??0}function lessonLink(id,label){return `<a href="#lesson/${id}">${esc(label)}</a>`}function head(title,sub){return `<div class="intro"><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>`}function pctbar(n){return `<div class="bar"><span style="width:${n}%"></span></div>`}
function render(){
 stop(false);route=location.hash.slice(1)||'home';
 if(route==='home'){route=state.curriculumRevision===2?'lesson/'+(Number.isInteger(state.last)?state.last:0):'route';state.curriculumRevision=2;save()}
 const [page,id]=route.split('/');document.body.dataset.page=page;
 $('#nav').innerHTML=NAV.map(([r,icon,label],index)=>`<a class="${page===r||(page==='module'&&r==='route')||(page==='lesson'&&r==='route')||(page==='exercise'&&r==='exercises')?'active':''}" href="#${r}">${navIcon(index)}${label}</a>`).join('');
 $('#crumb').textContent=({lesson:'课程学习',exercise:'练习',project:'项目实践',module:'课程模块',settings:'设置与备份'})[page]||NAV.find(n=>n[0]===page)?.[2]||'AI 学习';
 document.body.classList.toggle('dark',state.theme==='dark');$('#theme').textContent=state.theme==='dark'?'浅色':'深色';
 const views={route:roadmap,module:()=>modulePage(id),paths,resources,lesson:()=>lesson(Number(id)),exercises,exercise:()=>exercise(Number(id)),projects,project:()=>projectPage(Number(id)),review,notes,settings,search};
 const html=(views[page]||roadmap)();
 $('#main').innerHTML=['lesson','exercise','project'].includes(page)?html:`<div class="study-layout"><div class="study-content">${html}</div><aside class="lesson-lab general-lab" aria-label="自由编程练手区">${freeWorkspace()}</aside></div>`;
 $('#directory').innerHTML=`<input id="directory-search" type="search" placeholder="查找章节…" aria-label="查找章节"><div id="directory-list">${directoryHtml('')}</div>`;
 $('#directory-search').oninput=e=>$('#directory-list').innerHTML=directoryHtml(e.target.value);
 const meter=$('#sidebar-progress');if(meter)meter.innerHTML=`<div class="sidebar-progress"><div class="row"><span>我的学习进度</span><span>${state.done.length} / ${LESSONS.length}</span></div>${pctbar(progress())}</div>`;
 bind(page,Number(id));bindCatalog(page,id);bindWorkspace(page,Number(id));window.scrollTo({top:0,behavior:'instant'});
}
const STAGES=MODULES.map(m=>m.title);

function directoryHtml(query){
 const q=query.trim().toLowerCase();const current=route.startsWith('lesson/')?LESSONS[Number(route.split('/')[1])]?.module:route.startsWith('module/')?route.split('/')[1]:'';
 return [...new Set(MODULES.map(m=>m.category))].map(category=>{
  const modules=MODULES.filter(m=>m.category===category).map(m=>({m,items:LESSONS.filter(l=>l.module===m.key&&(!q||(category+m.title+l.title+l.body).toLowerCase().includes(q)))})).filter(x=>x.items.length);
  if(!modules.length)return '';
  return `<details class="directory-group" ${q||modules.some(x=>x.m.key===current)?'open':''}><summary>${esc(category)} <small>${modules.reduce((n,x)=>n+x.items.length,0)} 节</small></summary><div class="directory-modules">${modules.map(({m,items})=>`<details class="directory-module" ${m.key===current||q?'open':''}><summary>${esc(m.title)} <small>${items.length}</small></summary>${items.map(l=>`<a class="${route==='lesson/'+l.id?'current':''}" href="#lesson/${l.id}"><span>${String(l.id+1).padStart(2,'0')}</span>${esc(l.title.replace(/^开始：/,''))}${state.done.includes(l.id)?'<b>✓</b>':''}</a>`).join('')}<a class="module-overview" href="#module/${m.key}">模块概览 →</a></details>`).join('')}</div></details>`;
 }).join('')||'<small>没有匹配的章节。</small>';
}

function catalogRows(category='',q=''){
 q=q.trim().toLowerCase();const modules=MODULES.filter(m=>(!category||m.category===category)&&(!q||(m.title+m.category+m.goal+LESSONS.filter(l=>l.module===m.key).map(l=>l.title).join(' ')).toLowerCase().includes(q)));
 return [...new Set(modules.map(m=>m.category))].map(group=>{const ms=modules.filter(m=>m.category===group),ls=LESSONS.filter(l=>ms.some(m=>m.key===l.module));return `<details class="catalog-group" ${category||q?'open':''}><summary><span>${esc(group)}</span><small>${ms.length} 个模块 · ${ls.length} 节课 · 已完成 ${ls.filter(l=>state.done.includes(l.id)).length} 节</small></summary><div class="catalog-group-content">${ms.map(m=>{const items=LESSONS.filter(l=>l.module===m.key);return `<section class="catalog-module"><div class="row"><h2><a href="#module/${m.key}">${esc(m.title)}</a></h2><span class="badge">${items.filter(l=>state.done.includes(l.id)).length}/${items.length} 节</span></div><p>${esc(m.goal)}</p><div class="module-links">${items.map(l=>`<a href="#lesson/${l.id}">${esc(l.title)}</a>`).join('')}</div></section>`}).join('')}</div></details>`}).join('')||'<p class="empty">没有匹配课程。</p>';
}
function roadmap(){const cats=[...new Set(MODULES.map(m=>m.category))];return head('AI 课程目录',`${LESSONS.length} 节课程 · ${MODULES.length} 个模块 · ${EXERCISES.length} 道练习 · ${AI_PROJECTS.length+1} 个项目。`)+`<section class="continue-card"><small>继续你的学习</small><h2>${esc(LESSONS[Number.isInteger(state.last)?state.last:0]?.title||LESSONS[0].title)}</h2><p>已完成 ${state.done.length} 节课 · 今日也向前迈一步</p><a href="#lesson/${Number.isInteger(state.last)?state.last:0}">回到课程 <span>↗</span></a></section><div class="catalog-tools"><input id="catalog-query" type="search" placeholder="搜索：线性代数、机器学习、Transformer、RAG…" aria-label="搜索课程目录"><select id="catalog-category" aria-label="按学习领域筛选"><option value="">全部领域</option>${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select><a href="#paths">推荐学习路线 →</a></div><div id="catalog-results">${catalogRows()}</div>`}
function modulePage(key){const m=MODULES.find(m=>m.key===key);if(!m)return head('模块不存在','请返回课程目录。');const ls=LESSONS.filter(l=>l.module===key);return head(m.title,m.goal)+`<div class="module-meta"><span>${esc(m.category)} · ${m.level} · ${ls.length} 节</span><span>前置：${esc(m.prereq)}</span><span>已完成 ${ls.filter(l=>state.done.includes(l.id)).length} 节</span></div><div class="module-lesson-list">${ls.map(l=>`<a href="#lesson/${l.id}"><div><strong>${state.done.includes(l.id)?'✓ ':''}${esc(l.title)}</strong><p>${esc(l.problem)}</p></div><small>${l.minutes} 分钟 →</small></a>`).join('')}</div><div class="toolbar"><button class="primary" onclick="go('lesson/${ls.find(l=>!state.done.includes(l.id))?.id??ls[0].id}')">继续本模块</button><a href="#exercises" >打开练习 →</a></div>`}
function paths(){return head('学习路线','选择一条主线；所有课程仍可自由访问。数学不熟悉时，回到相关前置模块。')+LEARNING_PATHS.map(path=>`<section class="catalog-module"><h2>${esc(path.title)}</h2><p>${esc(path.description)}</p><ol class="path-list">${path.modules.map(key=>{const m=MODULES.find(m=>m.key===key);return `<li><a href="#module/${key}">${esc(m.title)}</a><small>${esc(m.goal)}</small></li>`}).join('')}</ol></section>`).join('')}

function resources(){
 const groups=[...new Set(MODULES.map(m=>m.category))];
 return head('学习资料','按学习领域归档。展开一个分类，查看对应课程和参考资料。')+`<div class="resource-groups">${groups.map(category=>{const modules=MODULES.filter(m=>m.category===category),ls=LESSONS.filter(l=>modules.some(m=>m.key===l.module)),links=new Map();ls.forEach(l=>{const url=l.sourceUrl||(l.ref?'https://www.runoob.com/python3/'+l.ref:'');if(url)links.set(url,l.sourceTitle||l.title)});return `<details class="catalog-group resource-group"><summary><span>${esc(category)}</span><small>${ls.length} 节课 · ${links.size} 份资料</small></summary><div class="catalog-group-content"><h3>配套课程</h3><div class="module-links">${modules.map(m=>`<a href="#module/${m.key}">${esc(m.title)}</a>`).join('')}</div><h3>参考阅读</h3>${[...links].map(([url,title])=>`<div class="lesson-row"><a href="${esc(url)}" target="_blank" rel="noopener">${esc(title)} ↗</a></div>`).join('')}</div></details>`}).join('')}</div><details class="catalog-group"><summary><span>本地运行与环境</span><small>Python · NumPy · pandas · PyTorch</small></summary><div class="catalog-group-content"><p>右侧练手区支持 Python 标准库，可离线运行。NumPy、pandas、PyTorch 框架示例请下载到本机独立环境运行。</p><pre class="hint">python -m venv .venv\n# Windows 激活\n.venv\\Scripts\\activate\n# macOS / Linux 激活\nsource .venv/bin/activate\n# 按需安装\npython -m pip install numpy pandas matplotlib</pre><a href="https://pytorch.org/get-started/locally/" target="_blank" rel="noopener">PyTorch 官方安装说明 ↗</a></div></details>`;
}
function bindCatalog(page,id){if(page==='route'){const filter=()=>$('#catalog-results').innerHTML=catalogRows($('#catalog-category').value,$('#catalog-query').value);$('#catalog-query').oninput=filter;$('#catalog-category').onchange=filter}
 if(page==='exercises'){const update=()=>$('#exercise-list').innerHTML=exerciseRows($('#exercise-filter').value,$('#exercise-query').value,$('#exercise-difficulty').value,$('#exercise-status').value,$('#exercise-source').value);['exercise-filter','exercise-difficulty','exercise-status','exercise-source'].forEach(id=>$('#'+id).onchange=update);$('#exercise-query').oninput=update}
 if(page==='lesson')bindBeginner(Number(id));
 if(page==='lesson'&&LESSONS[Number(id)]?.framework){$('#download-framework').onclick=()=>download('lesson-'+id+'-local.py',LESSONS[Number(id)].framework,'text/x-python')}
 if(page==='project'&&Number(id)>0)bindProject(Number(id));
}


function lessonTask(id){return EXERCISES.find(x=>x.lesson===id)}
function lessonLabMode(id){return state.labModes?.[id]||'practice'}
function activeEditorKey(page,id){
 if(page==='lesson'){const mode=lessonLabMode(id);return mode==='example'?'lesson-'+id:'lesson-'+mode+'-'+id}
 if(page==='project')return id===0?'project-main':'project-'+id;
 if(page==='exercise')return 'exercise-'+id;
 return 'scratch-'+route;
}
function freeWorkspace(){return `<div class="workspace-heading"><h2>自由练手</h2><span class="badge">Python</span></div><p class="lab-reading-note">边看边写，试试刚学到的知识。此页草稿会自动保存。</p>${editor(activeEditorKey(route.split('/')[0],Number(route.split('/')[1])),'# 在这里写下你的想法\n\n')}`}
function lessonWorkspace(id){
 const mode=lessonLabMode(id),x=lessonTask(id),l=LESSONS[id];
 const task=mode==='practice'?`<section class="lab-task"><span class="badge">本节小练习${state.lessonPractice?.[id]?.passed?' · ✓ 已通过':''}</span><h3>${esc(x.title)}</h3><p>${esc(x.desc)}</p>${x.taskData?`<pre class="hint">${esc(x.taskData)}</pre>`:''}${x.cases?`<p>实现 <code>${esc(x.signature)}</code>，使用 return 返回结果。</p><details><summary>查看输入与返回值</summary>${casePreview(x)}</details>`:`<details><summary>查看预期输出${x.input?'与输入':''}</summary>${x.input?`<p>标准输入：</p><pre>${esc(x.input)}</pre>`:''}<p>预期输出：</p><pre>${esc(x.expected)}</pre></details>`}<div class="lab-task-actions"><button id="lesson-test" class="primary">检验练习</button><details><summary>提示</summary>${x.hints.map(h=>`<p>${esc(h)}</p>`).join('')}</details><details><summary>参考答案</summary><pre class="hint">${esc(x.answer)}</pre></details></div><div id="test-result" role="status" aria-live="polite"></div></section>`:`<p class="lab-reading-note">${mode==='example'?'修改教学示例，观察结果；不会覆盖你的练习草稿。':'从空白开始自由编程，草稿按课程单独保存。'}</p>`;
 const starter=mode==='example'?l.code:mode==='practice'?(x.starter||'# '+x.title+'\n# '+x.desc.split('\n').join('\n# ')+'\n\n'):'# 自由练手：'+l.title+'\n\n';
 return `<div class="workspace-heading"><h2>练习工作台</h2><span class="badge">随学随练</span></div><div class="lab-tabs" role="tablist" aria-label="选择代码草稿">${[['practice','本节练习'],['example','教学示例'],['scratch','自由练手']].map(([value,label])=>`<button role="tab" aria-selected="${mode===value}" aria-controls="lab-document" id="lab-tab-${value}" data-lab-mode="${value}" ${mode===value?'class="active"':''}>${label}</button>`).join('')}</div><div id="lab-document" role="tabpanel" aria-labelledby="lab-tab-${mode}">${task}${editor(activeEditorKey('lesson',id),starter,mode==='example'?(id===3?'15':''):mode==='practice'?x.input||'':'')}</div>`;
}
function bindWorkspace(page,id){
 if(page!=='lesson')return;
 $$('[data-lab-mode]').forEach(button=>button.onclick=()=>{const top=window.scrollY;state.labModes??={};state.labModes[id]=button.dataset.labMode;save();render();window.scrollTo(0,top)});
 const test=$('#lesson-test');if(test)test.onclick=()=>run(true,lessonTask(id).expected,0);
}

function editor(key,code,input=''){return `<section class="panel editor-panel"><div class="editor-top"><span>●　${key==='project-main'?'learning_report.py':key.startsWith('project')?'ai_project.py':'practice.py'}</span><span id="save-status" class="saved">自动保存</span></div><div class="code-wrap"><div class="lines" id="lines"></div><div class="code-area"><pre id="highlight" aria-hidden="true"></pre><textarea id="code" aria-label="Python 代码编辑器" spellcheck="false" wrap="off">${esc(state.codes[key]??code)}</textarea></div></div><div class="console-input"><label for="stdin">标准输入 · 每行对应一次 input()</label><textarea id="stdin" placeholder="需要 input() 时在此输入">${esc(input)}</textarea></div><div class="editor-controls"><button class="primary" id="run">▶ 运行代码</button><button id="stop" disabled>停止</button><button class="plain" id="reset">重置</button><small id="runtime-state" style="margin-left:auto">Python · 浏览器运行</small></div><div class="console" id="console"><small>运行结果</small><pre id="output">点击运行，看看会发生什么。</pre></div><div style="padding:0 18px 15px"><small>运行快捷键：Ctrl / ⌘ + Enter。文件为临时文件，每次运行最长 30 秒。</small></div></section>`}
function mastery(id){if(state.mastery[id])return state.mastery[id];let attempts=EXERCISES.filter(x=>x.lesson===id).map(x=>state.attempts[x.id]).filter(Boolean);if(attempts.some(x=>x.passed&&x.hints===0))return '基本掌握';if(attempts.some(x=>!x.passed||x.hints>0))return '需要巩固';return state.done.includes(id)?'初步接触':'尚未学习'}
function lesson(id){return BEGINNER_GUIDES[id]&&!state.outlineMode?beginnerLesson(id):compactLesson(id)}
function compactLesson(id){const l=LESSONS[id];if(!l)return '<p>找不到课程。</p>';state.last=id;save();const paragraphs=l.body.split('\n').map(p=>`<p>${esc(p)}</p>`).join('');const next=id<LESSONS.length-1;const sourceUrl=l.sourceUrl||'https://www.runoob.com/python3/'+l.ref;return `<div class="lesson-top"><h1>${esc(l.title)}</h1><button id="font" aria-label="调整讲解字号">字号</button><button id="read-mode">切换零基础详解</button><button id="focus">专注</button><button id="favorite">${state.favorites.includes(id)?'★ 已收藏':'☆ 收藏'}</button></div><div class="lesson-context"><a href="#module/${l.module}">${esc(l.stage)}</a> · ${l.level||'入门'} · 第 ${id+1} / ${LESSONS.length} 节</div><div class="lesson-layout"><section class="panel prose"><h2>${esc(l.problem)}</h2><small>前置：${esc(l.prereq||'Python 基础')}</small><h3>知识说明</h3>${paragraphs}${l.formula?`<h3>核心公式 / 流程</h3><div class="formula">${esc(l.formula)}</div>`:''}<h3>实验说明</h3><p>${esc(l.explain)}</p>${l.expected!==undefined?`<details class="answer-details"><summary>查看示例预期输出</summary><pre>${esc(l.expected)}</pre></details>`:''}<div class="callout"><strong>常见误区</strong><br>${esc(l.error)}</div>${l.check?`<h3>理解自测</h3><p>${esc(l.check)}</p><details class="answer-details"><summary>展开参考解释</summary><p>${esc(l.checkAnswer)}</p></details>`:''}<h3>练习与进度</h3><p>先修改实验参数并预测结果，再运行。计算题使用标准库；请根据题目要求输出。</p><div class="toolbar"><button class="primary" onclick="go('exercise/${relatedExercise(id)}')">动手练习 →</button><button id="done">${state.done.includes(id)?'✓ 已学完':'标记本节已学完'}</button></div><label>掌握状态 <select id="mastery" class="select-state">${['尚未学习','初步接触','需要巩固','基本掌握'].map(s=>`<option ${mastery(id)===s?'selected':''}>${s}</option>`).join('')}</select></label><h3>笔记</h3><textarea class="note" id="note" placeholder="用自己的话解释这个知识点……">${esc(state.notes[id]||'')}</textarea><span id="note-status" class="saved">自动保存在此浏览器</span><h3>本节回顾</h3><p>${esc(l.formula||l.explain)}</p><div class="row"><a href="#${id?'lesson/'+(id-1):'route'}">← ${id?'上一节':'课程目录'}</a><a href="#${next?'lesson/'+(id+1):'projects'}">${next?'下一节':'项目实践'} →</a></div><a class="source" href="${esc(sourceUrl)}" target="_blank" rel="noopener">延伸阅读：${esc(l.sourceTitle||'菜鸟教程')} ↗</a></section><div class="lesson-lab">${lessonWorkspace(id)}${l.framework?`<section class="framework-example"><h3>本地框架示例</h3><p>需在本机安装对应依赖后运行；下方代码不在浏览器执行，也尚未在本机安装依赖验证。</p><button id="download-framework">下载 .py 文件</button><pre class="hint">${esc(l.framework)}</pre><a href="#resources">查看环境与资料 →</a></section>`:''}</div></div>`}
function practiceSource(x){return x.source?`<details class="practice-source"><summary>参考来源</summary><p>原创练习 · 教学参考</p><a target="_blank" rel="noopener" href="${esc(x.source.url)}">${esc(x.source.title)} ↗</a></details>`:''}
function pyValue(v){if(v===null)return 'None';if(v===true)return 'True';if(v===false)return 'False';if(Array.isArray(v))return '['+v.map(pyValue).join(', ')+']';if(typeof v==='object')return '{'+Object.entries(v).map(([k,v])=>JSON.stringify(k)+': '+pyValue(v)).join(', ')+'}';return JSON.stringify(v)}
function casePreview(x){return `<h3>函数接口</h3><pre class="hint">${esc(x.signature)}</pre><p>使用 return 返回结果，提交时自动检验。</p><h3>输入与返回值示例</h3><div class="case-table"><table><thead><tr><th>函数调用（Python）</th><th>期望返回值</th></tr></thead><tbody>${x.cases.map(c=>`<tr><td><code>${esc(x.function+"("+c.args.map(pyValue).join(", ")+")")}</code></td><td><code>${esc(pyValue(c.expected))}</code></td></tr>`).join('')}</tbody></table></div><p class="muted">试跑示例：将下面一行放在函数定义后。</p><pre class="hint">${esc("print("+x.function+"("+x.cases[0].args.map(pyValue).join(", ")+"))")}</pre><h3>约束与验收</h3><p>${esc(x.constraints)}</p><p>${x.cases.length} 个公开测试覆盖普通输入和部分边界；通过不代表所有可能输入都正确。</p>`}
function exerciseRows(module='',query='',difficulty='',status='',source=''){const items=EXERCISES.filter(x=>(!module||LESSONS[x.lesson]?.module===module)&&(!query||(x.title+x.desc+(x.source?.title||'')).toLowerCase().includes(query.toLowerCase()))&&(!difficulty||(x.difficulty||'课程配套')===difficulty)&&(!status||(status==='passed'?state.attempts[x.id]?.passed:status==='new'?!!x.cases:!state.attempts[x.id]?.passed))&&(!source||x.sourceKey===source)).sort((a,b)=>Number(!!b.cases)-Number(!!a.cases));return `<p class="muted">找到 ${items.length} 道题</p>`+items.map(x=>`<a class="panel" href="#exercise/${x.id}"><div class="row"><span class="badge">${esc(x.difficulty||'课程配套')}</span><small>${x.cases?x.cases.length+' 例行为验证':'示例输出验证'}</small></div><h3>${esc(x.title)}</h3><p>${esc(x.desc)}</p><small>${state.attempts[x.id]?.passed?'✓ 已通过':'待完成'} · ${esc(LESSONS[x.lesson]?.stage||'Python')} ${x.minutes?'· 约'+x.minutes+'分钟':''} →</small>${x.source?`<p class="muted">教学参考：${esc(x.source.title)}</p>`:''}</a>`).join('')}
function exercises(){return head('练习',`${EXERCISES.length} 道练习`)+`<div class="catalog-tools"><input id="exercise-query" type="search" placeholder="搜索：矩阵、CSV、检索……" aria-label="搜索练习"></div><details class="practice-filters"><summary>筛选</summary><div class="catalog-tools"><select id="exercise-filter" aria-label="按课程模块筛选练习"><option value="">全部模块</option>${MODULES.map(m=>`<option value="${m.key}">${esc(m.title)}</option>`).join('')}</select><select id="exercise-difficulty" aria-label="难度"><option value="">全部难度</option>${['入门','基础','挑战','课程配套'].map(x=>`<option>${x}</option>`).join('')}</select><select id="exercise-status" aria-label="完成状态"><option value="">全部状态</option><option value="new">函数题</option><option value="todo">尚未通过</option><option value="passed">已通过</option></select><select id="exercise-source" aria-label="教学参考"><option value="">全部教学参考</option>${[['cs50','Harvard CS50P'],['mit','MIT 6.0001'],['think','Think Python'],['d2l','动手学深度学习'],['isl','统计学习导论']].map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><span>已通过 ${passed()} / ${EXERCISES.length}</span><a href="#projects">项目实践 →</a></div></details><div class="exercise-grid" id="exercise-list">${exerciseRows()}</div>`}
function exercise(id){const x=EXERCISES[id];if(!x)return '<p>找不到练习。</p>';return `<div class="lesson-top"><h1>${esc(x.title)}</h1><a href="#exercises">返回练习工坊 →</a></div><div class="lesson-layout"><section class="panel prose"><span class="eyebrow">EXERCISE ${String(id+1).padStart(2,'0')} · ${esc(x.difficulty||'课程配套')}</span><h2>题目要求</h2><p>${esc(x.desc)}</p>${x.cases?casePreview(x):`${x.taskData?`<h3>给定数据</h3><pre class="hint">${esc(x.taskData)}</pre>`:''}<div class="callout">输入：${x.input?esc(x.input):'无需输入'}<br>预期输出：<code>${esc(x.expected)}</code><br>约束：使用 Python 3；不要输出额外说明文字。</div><p>提交时执行代码，比较实际输出与预期输出。本题只验证给定示例。</p>`}<div class="toolbar"><button id="test" class="primary">提交并检验</button><button id="hint">查看下一层提示</button><button id="answer">查看参考答案</button></div><div id="test-result" role="status"></div><div id="hints"></div><div id="answer-box"></div>${practiceSource(x)}<a class="source" href="#lesson/${x.lesson}">回到相关课程 →</a></section>${editor('exercise-'+id,x.starter||'# 在这里编写你的答案\n',x.input)}</div>`}
const projectStarter='# 学习时间统计器\nminutes = [20, 30, 15, 25, 40]\n\n# 1. 定义 summary(values)，返回总时长和平均时长\n# 2. 输出总时长和平均时长\n# 3. 统计至少学习25分钟的天数\n';const projectAnswer='minutes = [20, 30, 15, 25, 40]\ndef summary(values):\n    total = sum(values)\n    average = total / len(values) if values else 0\n    return total, average\ntotal, average = summary(minutes)\nprint(total)\nprint(average)\nprint(sum(1 for n in minutes if n >= 25))';
function legacyProject(){return head('项目：学习时间统计器','按步骤完成，再运行验收。')+`<div class="lesson-layout"><section class="panel prose"><span class="badge">入门项目 · 约 30 分钟</span><h2 style="margin-top:18px">我的学习时间统计器</h2><p>使用一周的样例数据，计算总学习时间、平均时间和达标天数。完成后你可以替换成自己的记录。</p><div class="two"><div><h3>你会用到</h3><p>列表、遍历、函数、条件判断、基础统计。建议先完成前 10 节课。</p></div><div><h3>最终效果</h3><p>样例 [20, 30, 15, 25, 40] 输出三行：130、26.0、3。</p></div></div>${pctbar(state.project.steps.length/3*100)}${['准备数据：建立列表，输出总时长 130。','组织函数：定义 summary(values)，返回总和与平均值。','统计达标：计算至少25分钟的天数，运行完整验收。'].map((s,i)=>`<div class="step"><label><input type="checkbox" class="project-step" data-step="${i}" ${state.project.steps.includes(i)?'checked':''}>${s}</label><small>提示：${['用 sum 汇总列表。','平均数 = 总和 / 数量，记得考虑空列表。','遍历列表，用条件统计符合要求的项。'][i]}</small></div>`).join('')}<div class="toolbar"><button class="primary" id="project-test">检验项目</button><button id="project-answer">查看参考实现</button></div><div id="test-result"></div><div id="answer-box"></div><p>扩展挑战：把记录保存为 JSON；允许读取不同周的数据；计算最长学习时长。文件操作在浏览器虚拟系统中完成，不会修改真实文件。</p></section><div class="lesson-lab">${editor('project-main',projectStarter)}</div></div>`}

function projects(){return head('项目实践',`${AI_PROJECTS.length+1} 个项目`)+`<section class="catalog-module"><h2><a href="#project/0">Python：学习时间统计器</a></h2><p>统计学习时长、平均值与达标天数。</p></section>${[...AI_PROJECTS].sort((a,b)=>Number(!!b.cases)-Number(!!a.cases)).map(pr=>`<section class="catalog-module"><div class="row"><h2><a href="#project/${pr.id}">${esc(pr.title)}</a></h2><span class="badge">${state.aiProjects?.[pr.id]?.completedAt?"✓ 已通过验收 · ":""}${state.aiProjects?.[pr.id]?.steps?.length||0} / ${pr.steps.length} 步</span></div><p>${esc(pr.description)}</p><small>前置：${esc(pr.prereq)}${pr.minutes?` · 约${pr.minutes}分钟`:""}</small><div><a href="#project/${pr.id}">开始 / 继续项目 →</a></div></section>`).join('')}`}
function projectPage(id){if(id===0)return legacyProject();const pr=AI_PROJECTS.find(p=>p.id===id);if(!pr)return head('项目不存在','请返回项目列表。');state.aiProjects??={};state.aiProjects[id]??={steps:[]};const ps=state.aiProjects[id];return head(pr.title,pr.description)+`${ps.completedAt?'<p class="notice">✓ 已通过项目验收，完成记录已保存。</p>':""}<div class="lesson-layout"><section class="panel prose"><small>前置：${esc(pr.prereq)}${pr.minutes?` · 约${pr.minutes}分钟`:""}</small><h3>实现步骤</h3>${pr.steps.map((step,i)=>`<div class="step"><label><input type="checkbox" class="ai-project-step" data-step="${i}" ${ps.steps.includes(i)?'checked':''}>${esc(step)}</label><details><summary>这一步的提示</summary><p>${esc(pr.hints[i])}</p></details></div>`).join('')}${pr.cases?casePreview(pr):`<h3>验收输出</h3><pre class="hint">${esc(pr.expected)}</pre>`}${pr.components?`<h3>先做这些组件练习</h3><p>${pr.components.map(name=>{const x=EXERCISES.find(x=>x.function===name);return `<a href="#exercise/${x.id}">${esc(x.title)}</a>`}).join(" · ")}</p>`:""}<div class="toolbar"><button class="primary" id="ai-project-test">运行验收</button><button id="ai-project-answer">参考实现</button></div><div id="test-result" role="status"></div><div id="answer-box"></div><h3>扩展挑战</h3><p>${esc(pr.extension)}</p>${practiceSource(pr)}<a href="#projects">← 返回项目列表</a></section><div class="lesson-lab">${editor('project-'+id,pr.code)}</div></div>`}
function bindProject(id){const pr=AI_PROJECTS.find(p=>p.id===id);if(!pr)return;$$('.ai-project-step').forEach(el=>el.onchange=()=>{const ps=state.aiProjects[id],n=Number(el.dataset.step);ps.steps=el.checked?[...new Set([...ps.steps,n])]:ps.steps.filter(x=>x!==n);save()});$('#ai-project-test').onclick=()=>run(true,pr.expected,0);$('#ai-project-answer').onclick=()=>$('#answer-box').innerHTML=`<pre class="hint">${esc(pr.answer)}</pre><p>${esc(pr.walkthrough||'按步骤构建，再执行完整验收。')}</p>`}
function review(){return head('复习','根据练习记录和自评选择需要巩固的课程。')+`<section class="panel">${LESSONS.map(l=>`<div class="lesson-row"><a href="#lesson/${l.id}">${esc(l.title)}</a><div class="row"><span class="badge">${mastery(l.id)}</span><a href="#exercise/${relatedExercise(l.id)}">再练一次 →</a></div></div>`).join('')}</section>`}
function notes(){const all=LESSONS.filter(l=>state.notes[l.id]||state.favorites.includes(l.id));return head('笔记与收藏','自动保存，可导出 Markdown。')+`<div class="toolbar"><button id="export-notes">导出笔记为 Markdown</button></div><div class="notes-list">${all.length?all.map(l=>`<section class="panel"><div class="row"><h3>${esc(l.title)}</h3>${state.favorites.includes(l.id)?'<span class="badge">★ 收藏</span>':''}</div><p style="white-space:pre-wrap">${esc(state.notes[l.id]||'还没有笔记，开始记录你的理解。')}</p><a class="source" href="#lesson/${l.id}">回到课程编辑 →</a></section>`).join(''):'<div class="empty">还没有笔记。在课程中写下公式含义、实验结果或不理解的地方。</div>'}</div>`}
function settings(){return head('设置与备份','记录保存在当前浏览器。换浏览器或设备前，请导出备份。')+`<div class="route-grid"><section class="panel"><h2>学习偏好</h2><p>目标：${esc(state.profile.goal)}<br>基础：${esc(state.profile.level)}<br>每天：${Number(state.profile.daily)} 分钟<br>偏好：${esc(state.profile.style)}<br>系统：${esc(state.profile.os)}</p><button id="edit-profile">调整学习设置</button><h3 style="margin-top:28px">数据备份</h3><p>备份包含进度、笔记、练习提交、项目代码与个人设置。导入前会下载当前数据备份。</p><div class="toolbar"><button id="export-data">导出全部数据</button><button id="import-data">从备份恢复</button></div><input type="file" id="import-file" accept="application/json,.json" hidden><button class="plain" id="clear-data">清空本地学习记录</button></section><section class="panel"><h2>运行环境</h2><p>Python 由 Pyodide 在 Web Worker 中执行，支持标准库及浏览器兼容能力。暂不支持桌面 GUI、直接访问本机文件或任意系统命令。运行环境随网站打包，首次打开需要加载。</p><h3>参考资料</h3><a class="source" target="_blank" rel="noopener" href="https://www.runoob.com/python3/python3-tutorial.html">菜鸟教程 Python 3 ↗</a></section></div>`}
function search(){return head('搜索','查找课程、练习和自己的笔记。')+`<input id="search-input" type="search" placeholder="试试：线性代数、机器学习、注意力、RAG……" aria-label="搜索课程和笔记"><div id="search-results" class="results"></div>`}
function lineNumbers(){if(!$('#lines'))return;const code=$('#code').value;const inputBox=$('.console-input');if(inputBox)inputBox.style.display=/input\s*\(/.test(code)?'block':'none';$('#lines').textContent=Array.from({length:code.split('\n').length},(_,i)=>i+1).join('\n');const tokens=/(#[^\n]*|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\b(?:def|return|if|elif|else|for|while|in|import|from|as|with|try|except|assert|True|False|None|and|or|not|break|continue)\b|\b\d+(?:\.\d+)?\b)/g;let html='',last=0;for(const m of code.matchAll(tokens)){html+=esc(code.slice(last,m.index));const t=m[0];html+='<span class="tok-'+(t.startsWith('#')?'comment':t.startsWith('"')||t.startsWith("'")?'str':/^\d/.test(t)?'num':'key')+'">'+esc(t)+'</span>';last=m.index+t.length}$('#highlight').innerHTML=html+esc(code.slice(last))+'\n';syncEditor()}
function syncEditor(){if(!$('#highlight'))return;$('#highlight').scrollTop=$('#code').scrollTop;$('#highlight').scrollLeft=$('#code').scrollLeft;$('#lines').scrollTop=$('#code').scrollTop}
function bind(page,id){if($('#code')){const key=activeEditorKey(page,id);lineNumbers();$('#code').addEventListener('scroll',syncEditor);$('#code').addEventListener('input',()=>{state.codes[key]=$('#code').value;save();lineNumbers();$('#save-status').textContent=saving?'已保存':'保存失败'});$('#code').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();const el=e.target;const indent=(el.value.slice(0,el.selectionStart).split('\n').pop().match(/^ */)||[''])[0];const extra=el.value.slice(0,el.selectionStart).trimEnd().endsWith(':')?'    ':'';el.setRangeText('\n'+indent+extra,el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input'))}if(e.key==='Tab'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('    ',start,end,'end');el.dispatchEvent(new Event('input'))}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run(false)}});$('#run').onclick=()=>run(false);$('#stop').onclick=()=>stop(true);$('#reset').onclick=()=>{if(!confirm('重置当前代码？已编辑的内容将被替换。'))return;delete state.codes[key];save();render()}}
if(page==='lesson'){const l=LESSONS[id];if(!l)return;$('#note').oninput=e=>{state.notes[id]=e.target.value;save();$('#note-status').textContent=saving?'已保存':'保存失败，请导出备份'};$('#done').onclick=()=>{if(!state.done.includes(id))state.done.push(id);save();render();toast('本节学习记录已保存')};$('#mastery').onchange=e=>{state.mastery[id]=e.target.value;save()};$('#favorite').onclick=()=>{state.favorites=state.favorites.includes(id)?state.favorites.filter(i=>i!==id):[...state.favorites,id];save();render()};$('#font').onclick=()=>{state.font=state.font===18?16:18;save();document.documentElement.style.setProperty('--read-size',state.font+'px')};$('#focus').onclick=()=>document.body.classList.toggle('focus')}
if(page==='exercise'){const x=EXERCISES[id];if(!x)return;let count=Math.min(3,state.assistance?.[id]||0);$('#test').onclick=()=>run(true,x.expected,count);$('#hint').onclick=()=>{count=Math.min(3,count+1);state.assistance??={};state.assistance[id]=count;save();$('#hints').innerHTML=x.hints.slice(0,count).map((h,i)=>`<div class="hint">提示 ${i+1}：${esc(h)}</div>`).join('')};$('#answer').onclick=()=>{count=3;state.assistance??={};state.assistance[id]=count;save();$('#answer-box').innerHTML=`<h3>参考实现</h3><pre class="hint">${esc(x.answer)}</pre><p>思路：${esc(x.walkthrough||x.hints[0])}</p>`}}
if(page==='project'&&id===0){$$('.project-step').forEach(el=>el.onchange=()=>{const i=+el.dataset.step;state.project.steps=el.checked?[...new Set([...state.project.steps,i])]:state.project.steps.filter(n=>n!==i);save()});$('#project-test').onclick=()=>run(true,'130\n26.0\n3',0);$('#project-answer').onclick=()=>$('#answer-box').innerHTML=`<pre class="hint">${esc(projectAnswer)}</pre><p>先求总和与平均数，再逐项判断并累计达标天数。</p>`}
if(page==='notes')$('#export-notes').onclick=()=>download('Python学习笔记.md',LESSONS.filter(l=>state.notes[l.id]).map(l=>'# '+l.title+'\n\n'+state.notes[l.id]).join('\n\n'),'text/markdown');
if(page==='settings'){$('#edit-profile').onclick=openProfile;$('#export-data').onclick=exportData;$('#import-data').onclick=()=>$('#import-file').click();$('#import-file').onchange=importData;$('#clear-data').onclick=()=>{if(confirm('先下载备份，再清空当前浏览器的全部学习记录？')){exportData();localStorage.removeItem(KEY);location.reload()}}}
if(page==='search'){$('#search-input').focus();$('#search-input').oninput=e=>{const q=e.target.value.trim().toLowerCase();const ls=q?LESSONS.filter(l=>(l.title+l.stage+(l.formula||'')+l.body+(state.notes[l.id]||'')).toLowerCase().includes(q)):[];const xs=q?EXERCISES.filter(x=>(x.title+x.desc).toLowerCase().includes(q)):[];$('#search-results').innerHTML=ls.map(l=>`<a href="#lesson/${l.id}">课程 / 笔记　${esc(l.title)}　→</a>`).join('')+xs.map(x=>`<a href="#exercise/${x.id}">练习　${esc(x.title)}　→</a>`).join('')||`<div class="empty">${q?'没有找到相关内容，换个关键词试试。':'输入关键词开始查找。'}</div>`}}
}
function $$(s){return [...document.querySelectorAll(s)]}
function stop(visible){++runToken;if(worker){worker.terminate();worker=null}clearTimeout(timer);running=false;if($('#run'))$('#run').disabled=false;if($('#stop'))$('#stop').disabled=true;if(visible&&$('#output')){$('#output').textContent='运行已停止。你可以修改代码后重新运行。';$('#runtime-state').textContent='已停止'}}
function run(test,expected='',hints=0){if(running)return;const code=$('#code')?.value;if(code==null)return;running=true;const target=route.startsWith('lesson/')?lessonTask(Number(route.split('/')[1])):route.startsWith('exercise/')?EXERCISES[Number(route.split('/')[1])]:AI_PROJECTS.find(x=>x.id===Number(route.split('/')[1]));const tests=test&&target?.cases?{function:target.function,cases:target.cases}:null;if(test&&$('#test-result'))$('#test-result').textContent='正在检验……';$('#run').disabled=true;$('#stop').disabled=false;$('#console').classList.remove('error');$('#output').textContent='正在准备 Python 环境，首次运行可能需要一些时间……';$('#runtime-state').textContent='加载 / 运行中';const token=++runToken;worker=new Worker('runner.js');timer=setTimeout(()=>{if(token!==runToken)return;stop(true);$('#output').textContent='运行超过30秒，已终止。首次下载较慢可重试；也请检查是否存在无限循环。'},30000);worker.onerror=()=>finish({ok:false,out:'',err:'运行环境加载失败，请检查网络后重试。'});worker.onmessage=e=>finish(e.data);worker.postMessage({code,input:$('#stdin').value,tests});function finish(result){if(token!==runToken)return;const text=result.ok?result.out:result.err;clearTimeout(timer);worker.terminate();worker=null;running=false;$('#run').disabled=false;$('#stop').disabled=true;$('#runtime-state').textContent=result.ok?'运行完成':'出现错误';$('#console').classList.toggle('error',!result.ok);$('#output').textContent=text||(result.ok?'程序运行完成，没有输出。':'运行失败');if(!result.ok){let advice=result.err.includes('SyntaxError')?'检查冒号、括号和英文引号。':result.err.includes('NameError')?'检查变量名拼写，以及是否先赋值再使用。':result.err.includes('ValueError')?'检查输入是否符合数值格式。':result.err.includes('IndentationError')?'检查缩进是否统一使用四个空格。':'从错误最后一行开始，检查对应代码和输入。';$('#output').textContent+='\n\n建议：'+advice}if(test){const ok=result.ok&&(tests?result.tests?.length===tests.cases.length&&result.tests.every(x=>x.ok):result.out.trim()===expected.trim());$('#test-result').innerHTML=`<div class="notice">${ok?(tests?'✓ '+tests.cases.length+' 个测试全部通过！':'✓ 检验通过！你完成了这个示例。'):'还有测试未通过，请检查下面的反馈和错误信息。'}</div>${result.tests?`<ol class="test-cases">${result.tests.map((c,i)=>`<li>${c.ok?'✓':'✗'} 用例 ${i+1}：${esc(c.message)}</li>`).join('')}</ol>`:''}`;if(route.startsWith('lesson/')){const lid=Number(route.split('/')[1]);state.lessonPractice??={};const prior=state.lessonPractice[lid]||{};state.lessonPractice[lid]={passed:ok||!!prior.passed,lastPassed:ok,code,date:Date.now()};}if(route.startsWith('exercise/')){const id=+route.split('/')[1],prior=state.attempts[id]||{};state.attempts[id]={passed:ok||!!prior.passed,lastPassed:ok,hints:ok?hints:(prior.hints??hints),submissions:(prior.submissions||0)+1,code,date:Date.now()};}else if(route==='project/0'&&ok){state.project.steps=[0,1,2];$$('.project-step').forEach(e=>e.checked=true)}if(route.startsWith('project/')&&route!=='project/0'&&ok){const pid=Number(route.split('/')[1]);state.aiProjects[pid].steps=AI_PROJECTS.find(p=>p.id===pid).steps.map((_,i)=>i);state.aiProjects[pid].completedAt=Date.now();$$('.ai-project-step').forEach(e=>e.checked=true)}save()}}}
function download(name,body,type='application/json'){const u=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function exportData(){download('python-learning-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2))}
async function importData(e){try{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('文件过大');const obj=JSON.parse(await f.text());if(obj.version!==1||!obj.profile||!Array.isArray(obj.done)||!obj.notes||typeof obj.notes!=='object'||!obj.codes||!obj.attempts||!Array.isArray(obj.favorites)||!obj.mastery||!obj.project||!Array.isArray(obj.project.steps)||!Number.isFinite(obj.seconds)||!Number.isFinite(+obj.profile.daily))throw Error('不是有效的学习备份');if(!confirm('恢复此备份并替换当前记录？将先下载当前数据的备份。'))return;exportData();state=obj;save();render();toast('学习数据已恢复')}catch(err){toast('恢复失败：'+err.message)}}
function openProfile(){const form=$('#setup-form');for(const [k,v]of Object.entries(state.profile)){if(form.elements[k])form.elements[k].value=v}$('#setup').showModal()}
$('#setup-form').onsubmit=e=>{e.preventDefault();state.profile=Object.fromEntries(new FormData(e.target));state.profile.daily=+state.profile.daily;state.onboarded=true;save();$('#setup').close();render();toast('学习计划已更新')};$('#skip').onclick=()=>{state.onboarded=true;save();$('#setup').close()};$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save();document.body.classList.toggle('dark',state.theme==='dark');$('#theme').textContent=state.theme==='dark'?'浅色':'深色'};window.addEventListener('hashchange',render);document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();go('search')}});let activeAt=Date.now();['pointerdown','keydown','scroll'].forEach(n=>document.addEventListener(n,()=>activeAt=Date.now(),{passive:true}));setInterval(()=>{if(document.visibilityState==='visible'&&Date.now()-activeAt<60000){state.seconds+=10;save()}},10000);document.documentElement.style.setProperty('--read-size',(state.font||14)+'px');render();

async function updateServiceStatus(){
 const badge=document.getElementById('service-status');if(!badge)return;
 const local=['127.0.0.1','localhost'].includes(location.hostname);
 if(!local){badge.textContent='私人学习空间';return}
 try{const response=await fetch('/health',{cache:'no-store',signal:AbortSignal.timeout(3000)});const data=await response.json();if(data.status!=='ready')throw Error();badge.textContent='本机服务就绪';badge.classList.remove('offline');badge.title='登录 Windows 后自动启动；桌面入口可随时恢复服务。'}
 catch{badge.textContent='服务离线';badge.classList.add('offline');badge.title='双击桌面 AI 学习快捷方式，恢复本机服务。'}
}
updateServiceStatus();setInterval(updateServiceStatus,30000);
